// Maps API error codes to translated text. Exhaustive on purpose: a new server
// error code (Rust `ErrorCode`, regenerated by `make types`) fails the type check here.
import type { MessageKey } from '@cloudit/ui/i18n';
import { ApiError, type ClientErrorCode } from './api';

const MESSAGE_KEYS: Record<ClientErrorCode, MessageKey> = {
  bad_request: 'error.bad_request',
  not_found: 'error.not_found',
  unavailable: 'error.unavailable',
  internal: 'error.internal',
  network: 'error.network',
  unknown: 'error.unknown'
};

/** The i18n key describing any thrown value. */
export function errorMessageKey(err: unknown): MessageKey {
  return err instanceof ApiError ? MESSAGE_KEYS[err.code] : 'error.unknown';
}
